SELECT sku, name, pack, gtin
FROM store.products
WHERE name ILIKE '%atta%' OR name ILIKE '%wheat%';

SELECT status, COUNT(*) as cnt
FROM store.shelf_audits
GROUP BY status;

SELECT sku, name, pack
FROM store.products
WHERE name ILIKE '%snack%' OR name ILIKE '%chip%' OR name ILIKE '%namkeen%' OR name ILIKE '%biscuit%';

SELECT sku, name, pack
FROM store.products
ORDER BY name;

SELECT date, sku, units, reason
FROM store.write_offs
ORDER BY date;

SELECT *
FROM payments.customer_complaints
ORDER BY complaint_ts;

SELECT * FROM payments.upi_settlements
WHERE settlement_date >= '2026-06-01' AND settlement_date <= '2026-06-30'
ORDER BY settlement_date;
